  "paddock.rules.kicker": { en: "Competition standards", ca: "Estàndards de competició", fr: "Standards de compétition" },
  "paddock.rules.title": { en: "Code of conduct and track protocol", ca: "Codi de conducta i protocol de pista", fr: "Code de conduite et protocole de piste" },
  "paddock.rules.1.title": { en: "#01 · Safety first", ca: "#01 · Seguretat primer", fr: "#01 · Sécurité d'abord" },
  "paddock.rules.1.body": { en: "Aim for a low incident count (0x–4x) to protect the team's Class A licence and safety rating.", ca: "Objectiu d'incidents baixos (0x-4x) per preservar la llicència Class A i el safety rating de l'escuderia.", fr: "Objectif d'incidents bas (0x-4x) pour préserver la licence Class A et le safety rating de l'écurie." },
  "paddock.rules.2.title": { en: "#02 · Open telemetry", ca: "#02 · Telemetria oberta", fr: "#02 · Télémétrie ouverte" },
  "paddock.rules.2.body": { en: "Active Garage 61 sync in every official session so sector deltas can be compared.", ca: "Sincronització activa a Garage 61 en totes les sessions oficials per comparar deltes de sector.", fr: "Synchronisation Garage 61 active dans chaque session officielle pour comparer les deltas de secteur." },
  "paddock.rules.3.title": { en: "#03 · Radio discipline", ca: "#03 · Disciplina de ràdio", fr: "#03 · Discipline radio" },
  "paddock.rules.3.body": { en: "A clean Discord channel, with push-to-talk required in qualifying and pit stops.", ca: "Canal net a Discord amb push-to-talk obligatori durant les classificacions i les aturades a box.", fr: "Canal Discord propre, avec push-to-talk obligatoire en qualifications et aux arrêts au stand." },
  "paddock.rules.4.title": { en: "#04 · Sporting respect", ca: "#04 · Respecte esportiu", fr: "#04 · Respect sportif" },
  "paddock.rules.4.body": { en: "No toxicity. Safe rejoins and space for cars being lapped in multiclass.", ca: "Zero toxicitat. Reincorporacions segures i facilitació dels doblats en multiclase.", fr: "Zéro toxicité. Réinsertions sûres et facilitation des dépassements pour tour en multiclasse." },
