  "ai.prompt.balance": { en: "Give me a step-by-step guide to fix entry understeer and exit oversteer in a GT3 at Spa-Francorchamps.", ca: "Dona'm una guia pas a pas per corregir el subviratge d'entrada i el sobreviratge de sortida en un GT3 a Spa-Francorchamps.", fr: "Donne-moi un guide étape par étape pour corriger le sous-virage en entrée et le survirage en sortie sur une GT3 à Spa-Francorchamps." },
  "ai.prompt.tel": { en: "Which Garage 61 telemetry channels should I look at to find time under braking (trail braking) at Le Mans or Watkins Glen?", ca: "Quins canals de telemetria de Garage 61 he d'analitzar per guanyar dècimes en frenada (trail braking) a Le Mans o Watkins Glen?", fr: "Quels canaux de télémétrie Garage 61 dois-je regarder pour gagner du temps au freinage (trail braking) au Mans ou à Watkins Glen ?" },
  "ai.prompt.stint": { en: "How do we manage cold pressures, fuel and a double tyre stint in a 24-hour endurance race in iRacing?", ca: "Com gestionem les pressions en fred, el combustible i un doble stint de pneumàtics en una cursa de resistència de 24 h a iRacing?", fr: "Comment gère-t-on les pressions à froid, le carburant et un double relais pneus dans une course d'endurance de 24 h sur iRacing ?" },
  "ai.prompt.join": { en: "What are the requirements and the steps to join Muntrume Motorsport as an official driver?", ca: "Quins són els requisits i els passos per unir-me com a pilot oficial a Muntrume Motorsport?", fr: "Quelles sont les conditions et les étapes pour rejoindre Muntrume Motorsport comme pilote officiel ?" },
